export type ParsedBuyTicketsInstruction<
  TProgram extends string = typeof LOTTERY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    buyer: TAccountMetas[0];
    config: TAccountMetas[1];
    round: TAccountMetas[2];
    usdcMint: TAccountMetas[3];
    buyerTokenAccount: TAccountMetas[4];
    prizeVault: TAccountMetas[5];
    prizeVaultAuthority: TAccountMetas[6];
    lpVault: TAccountMetas[7];
    lpAuthority: TAccountMetas[8];
    lpPrincipal: TAccountMetas[9];
    buyerEntry: TAccountMetas[10];
    referrerAccount?: TAccountMetas[11] | undefined;
    tokenProgram: TAccountMetas[12];
    systemProgram: TAccountMetas[13];
    rent: TAccountMetas[14];
  };
  data: BuyTicketsInstructionData;
};

export function parseBuyTicketsInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBuyTicketsInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === LOTTERY_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      buyer: getNextAccount(),
      config: getNextAccount(),
      round: getNextAccount(),
      usdcMint: getNextAccount(),
      buyerTokenAccount: getNextAccount(),
      prizeVault: getNextAccount(),
      prizeVaultAuthority: getNextAccount(),
      lpVault: getNextAccount(),
      lpAuthority: getNextAccount(),
      lpPrincipal: getNextAccount(),
      buyerEntry: getNextAccount(),
      referrerAccount: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      rent: getNextAccount(),
    },
    data: getBuyTicketsInstructionDataDecoder().decode(instruction.data),
  };
}
